-- Module 12: immutable stock ledger with transactionally maintained balances.
insert into public.module_dependencies(module_key,dependency_module_key) values('inventory','product_catalog') on conflict do nothing;
insert into public.permissions(key,domain,action,description) values('inventory.manage','inventory','manage','Configure inventory items and locations'),('inventory.transfer','inventory','transfer','Transfer stock between locations'),('inventory.count','inventory','count','Perform physical counts') on conflict(key) do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_inventory_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager')and permission.key in('inventory.read','inventory.adjust','inventory.manage','inventory.transfer','inventory.count')on conflict do nothing;end;$$;
create function private.handle_main_branch_inventory_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_inventory_permissions(new.organization_id);end if;return new;end;$$;
create trigger zzzz_install_inventory_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_inventory_permissions();select private.install_inventory_permissions(id)from public.organizations;

create table public.inventory_locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,branch_id uuid not null,code text not null check(code~'^[a-z][a-z0-9_]{0,63}$'),name text not null check(char_length(btrim(name))between 1 and 120),location_type text not null check(location_type in('store','stockroom','warehouse')),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,code),foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict);
create index inventory_locations_branch_idx on public.inventory_locations(organization_id,branch_id);
create table public.inventory_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,product_variant_id uuid not null,low_stock_threshold numeric(16,4)not null default 0 check(low_stock_threshold>=0),reorder_level numeric(16,4)not null default 0 check(reorder_level>=0),is_tracked boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,product_variant_id),foreign key(product_variant_id,organization_id)references public.product_variants(id,organization_id)on delete restrict);
create index inventory_items_variant_idx on public.inventory_items(product_variant_id);
create table public.stock_transfers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,from_location_id uuid not null,to_location_id uuid not null,status text not null default'draft'check(status in('draft','completed','cancelled')),notes text check(char_length(notes)<=500),idempotency_key text not null,completed_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,idempotency_key),foreign key(from_location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict,foreign key(to_location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict,check(from_location_id<>to_location_id));
create index stock_transfers_locations_idx on public.stock_transfers(organization_id,from_location_id,to_location_id,created_at desc);
create table public.stock_adjustments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,location_id uuid not null,reason text not null check(char_length(btrim(reason))between 1 and 500),physical_count boolean not null,status text not null default'draft'check(status in('draft','pending_approval','approved','posted','rejected','cancelled')),approval_request_id uuid references public.approval_requests(id)on delete restrict,idempotency_key text not null,posted_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,idempotency_key),foreign key(location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict);
create index stock_adjustments_location_idx on public.stock_adjustments(organization_id,location_id,created_at desc);
create table public.stock_transfer_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,transfer_id uuid not null,inventory_item_id uuid not null,quantity numeric(16,4)not null check(quantity>0),unit_cost numeric(16,4)not null check(unit_cost>=0),unique(transfer_id,inventory_item_id),foreign key(transfer_id,organization_id)references public.stock_transfers(id,organization_id)on delete cascade,foreign key(inventory_item_id,organization_id)references public.inventory_items(id,organization_id)on delete restrict);
create index stock_transfer_lines_item_idx on public.stock_transfer_lines(inventory_item_id);
create table public.stock_adjustment_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,adjustment_id uuid not null,inventory_item_id uuid not null,counted_quantity numeric(16,4)check(counted_quantity>=0),requested_delta numeric(16,4),system_quantity numeric(16,4),posted_delta numeric(16,4),unit_cost numeric(16,4)check(unit_cost>=0),unique(adjustment_id,inventory_item_id),foreign key(adjustment_id,organization_id)references public.stock_adjustments(id,organization_id)on delete cascade,foreign key(inventory_item_id,organization_id)references public.inventory_items(id,organization_id)on delete restrict,check(counted_quantity is not null or requested_delta is not null));
create index stock_adjustment_lines_item_idx on public.stock_adjustment_lines(inventory_item_id);
create table public.stock_balances(id uuid primary key default gen_random_uuid(),organization_id uuid not null,inventory_item_id uuid not null,location_id uuid not null,quantity numeric(16,4)not null default 0,average_unit_cost numeric(16,4)not null default 0 check(average_unit_cost>=0),last_movement_at timestamptz,updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,inventory_item_id,location_id),foreign key(inventory_item_id,organization_id)references public.inventory_items(id,organization_id)on delete restrict,foreign key(location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict);
create index stock_balances_location_state_idx on public.stock_balances(organization_id,location_id,quantity);create index stock_balances_item_idx on public.stock_balances(inventory_item_id);
create table public.stock_movements(id uuid primary key default gen_random_uuid(),organization_id uuid not null,inventory_item_id uuid not null,location_id uuid not null,movement_type text not null check(movement_type in('purchase','sale','return','adjustment','transfer_in','transfer_out','opening_balance','wastage')),quantity_delta numeric(16,4)not null check(quantity_delta<>0),unit_cost numeric(16,4)not null check(unit_cost>=0),balance_after numeric(16,4)not null,transfer_id uuid,adjustment_id uuid,reference_type text,reference_id uuid,notes text check(char_length(notes)<=500),idempotency_key text not null,occurred_at timestamptz not null default now(),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,idempotency_key),foreign key(inventory_item_id,organization_id)references public.inventory_items(id,organization_id)on delete restrict,foreign key(location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict,foreign key(transfer_id,organization_id)references public.stock_transfers(id,organization_id)on delete restrict,foreign key(adjustment_id,organization_id)references public.stock_adjustments(id,organization_id)on delete restrict);
create index stock_movements_history_idx on public.stock_movements(organization_id,inventory_item_id,location_id,occurred_at desc);create index stock_movements_recent_idx on public.stock_movements(organization_id,occurred_at desc);create index stock_movements_reference_idx on public.stock_movements(organization_id,reference_type,reference_id)where reference_id is not null;
create trigger set_updated_at before update on public.inventory_locations for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.inventory_items for each row execute function private.set_updated_at();
create function private.reject_stock_movement_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception'Stock movements are immutable.'using errcode='P0001';end;$$;create trigger stock_movements_immutable before update or delete on public.stock_movements for each row execute function private.reject_stock_movement_mutation();
create function private.reject_stock_balance_direct_write()returns trigger language plpgsql set search_path='' as $$begin if current_setting('app.inventory_projection_write',true)is distinct from'on'then raise exception'Stock balances can only be changed by a stock movement.'using errcode='P0001';end if;return new;end;$$;create trigger stock_balances_projection_only before insert or update or delete on public.stock_balances for each row execute function private.reject_stock_balance_direct_write();

insert into public.inventory_locations(organization_id,branch_id,code,name,location_type)select branch.organization_id,branch.id,branch.code||'_stock',branch.name||' Stock','store'from public.branches branch on conflict(organization_id,code)do nothing;
create function private.create_default_inventory_location()returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.inventory_locations(organization_id,branch_id,code,name,location_type)values(new.organization_id,new.id,new.code||'_stock',new.name||' Stock','store')on conflict(organization_id,code)do nothing;return new;end;$$;create trigger create_default_inventory_location after insert on public.branches for each row execute function private.create_default_inventory_location();
insert into public.inventory_locations(organization_id,branch_id,code,name,location_type)select branch.organization_id,branch.id,branch.code||'_stock',branch.name||' Stock','store' from public.branches branch on conflict(organization_id,code)do nothing;
create function private.inventory_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='inventory');$$;
create function private.can_read_inventory_location(requested_organization_id uuid,requested_location_id uuid)returns boolean language sql stable security definer set search_path='' as $$select private.inventory_module_enabled(requested_organization_id)and exists(select 1 from public.inventory_locations location where location.id=requested_location_id and location.organization_id=requested_organization_id and private.can_business_permission(requested_organization_id,'inventory.read',location.branch_id));$$;
alter table public.inventory_locations enable row level security;alter table public.inventory_items enable row level security;alter table public.stock_balances enable row level security;alter table public.stock_movements enable row level security;alter table public.stock_transfers enable row level security;alter table public.stock_transfer_lines enable row level security;alter table public.stock_adjustments enable row level security;alter table public.stock_adjustment_lines enable row level security;
create policy inventory_locations_read on public.inventory_locations for select to authenticated using((select private.inventory_module_enabled(inventory_locations.organization_id))and private.can_business_permission(inventory_locations.organization_id,'inventory.read',inventory_locations.branch_id));
create policy inventory_items_read on public.inventory_items for select to authenticated using((select private.inventory_module_enabled(inventory_items.organization_id))and private.can_business_permission(inventory_items.organization_id,'inventory.read',null));
create policy stock_balances_read on public.stock_balances for select to authenticated using(private.can_read_inventory_location(stock_balances.organization_id,stock_balances.location_id));
create policy stock_movements_read on public.stock_movements for select to authenticated using(private.can_read_inventory_location(stock_movements.organization_id,stock_movements.location_id));
create policy stock_transfers_read on public.stock_transfers for select to authenticated using(private.can_read_inventory_location(stock_transfers.organization_id,stock_transfers.from_location_id)or private.can_read_inventory_location(stock_transfers.organization_id,stock_transfers.to_location_id));
create policy stock_transfer_lines_read on public.stock_transfer_lines for select to authenticated using(exists(select 1 from public.stock_transfers transfer where transfer.id=stock_transfer_lines.transfer_id and transfer.organization_id=stock_transfer_lines.organization_id and(private.can_read_inventory_location(stock_transfer_lines.organization_id,transfer.from_location_id)or private.can_read_inventory_location(stock_transfer_lines.organization_id,transfer.to_location_id))));
create policy stock_adjustments_read on public.stock_adjustments for select to authenticated using(private.can_read_inventory_location(stock_adjustments.organization_id,stock_adjustments.location_id));
create policy stock_adjustment_lines_read on public.stock_adjustment_lines for select to authenticated using(exists(select 1 from public.stock_adjustments adjustment where adjustment.id=stock_adjustment_lines.adjustment_id and adjustment.organization_id=stock_adjustment_lines.organization_id and private.can_read_inventory_location(stock_adjustment_lines.organization_id,adjustment.location_id)));

create function private.configure_inventory_item(requested_organization_id uuid,requested_inventory_item_id uuid,requested_product_variant_id uuid,requested_low_stock_threshold numeric,requested_reorder_level numeric,requested_is_tracked boolean)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_inventory_item_id,gen_random_uuid());begin if(select auth.uid())is null or not private.inventory_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'inventory.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_low_stock_threshold<0 or requested_reorder_level<0 or not exists(select 1 from public.product_variants variant join public.products product on product.id=variant.product_id and product.organization_id=variant.organization_id where variant.id=requested_product_variant_id and variant.organization_id=requested_organization_id and product.product_type='product')then raise exception'Invalid inventory item.'using errcode='22023';end if;if requested_inventory_item_id is not null and not exists(select 1 from public.inventory_items where id=target_id and organization_id=requested_organization_id and product_variant_id=requested_product_variant_id)then raise exception'Inventory item not found.'using errcode='22023';end if;insert into public.inventory_items(id,organization_id,product_variant_id,low_stock_threshold,reorder_level,is_tracked)values(target_id,requested_organization_id,requested_product_variant_id,requested_low_stock_threshold,requested_reorder_level,requested_is_tracked)on conflict(id)do update set low_stock_threshold=excluded.low_stock_threshold,reorder_level=excluded.reorder_level,is_tracked=excluded.is_tracked;return target_id;end;$$;
create function private.save_inventory_location(requested_organization_id uuid,requested_location_id uuid,requested_branch_id uuid,requested_code text,requested_name text,requested_type text,requested_is_active boolean)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_location_id,gen_random_uuid());begin if(select auth.uid())is null or not private.inventory_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'inventory.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_code!~'^[a-z][a-z0-9_]{0,63}$'or char_length(btrim(requested_name))not between 1 and 120 or requested_type not in('store','stockroom','warehouse')or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id)then raise exception'Invalid inventory location.'using errcode='22023';end if;if requested_location_id is not null and not exists(select 1 from public.inventory_locations where id=target_id and organization_id=requested_organization_id)then raise exception'Inventory location not found.'using errcode='22023';end if;insert into public.inventory_locations(id,organization_id,branch_id,code,name,location_type,is_active)values(target_id,requested_organization_id,requested_branch_id,requested_code,btrim(requested_name),requested_type,requested_is_active)on conflict(id)do update set branch_id=excluded.branch_id,code=excluded.code,name=excluded.name,location_type=excluded.location_type,is_active=excluded.is_active;return target_id;end;$$;

create function private.post_stock_movement(requested_organization_id uuid,requested_inventory_item_id uuid,requested_location_id uuid,requested_movement_type text,requested_quantity_delta numeric,requested_unit_cost numeric,requested_transfer_id uuid,requested_adjustment_id uuid,requested_reference_type text,requested_reference_id uuid,requested_notes text,requested_idempotency_key text,requested_actor uuid)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid;balance_row public.stock_balances%rowtype;next_quantity numeric;next_average numeric;allow_negative boolean:=false;begin select id into target_id from public.stock_movements where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return target_id;end if;if requested_movement_type not in('purchase','sale','return','adjustment','transfer_in','transfer_out','opening_balance','wastage')or requested_quantity_delta=0 or requested_unit_cost<0 or not exists(select 1 from public.inventory_items where id=requested_inventory_item_id and organization_id=requested_organization_id and is_tracked)or not exists(select 1 from public.inventory_locations where id=requested_location_id and organization_id=requested_organization_id and is_active)then raise exception'Invalid stock movement.'using errcode='22023';end if;perform set_config('app.inventory_projection_write','on',true);insert into public.stock_balances(organization_id,inventory_item_id,location_id)values(requested_organization_id,requested_inventory_item_id,requested_location_id)on conflict(organization_id,inventory_item_id,location_id)do nothing;select*into balance_row from public.stock_balances where organization_id=requested_organization_id and inventory_item_id=requested_inventory_item_id and location_id=requested_location_id for update;next_quantity:=balance_row.quantity+requested_quantity_delta;select coalesce((module.config->>'allow_negative_stock')::boolean,false)into allow_negative from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='inventory';if next_quantity<0 and not allow_negative then raise exception'Insufficient stock.'using errcode='P0001';end if;next_average:=case when requested_quantity_delta>0 and next_quantity>0 then round(((balance_row.quantity*balance_row.average_unit_cost)+(requested_quantity_delta*requested_unit_cost))/next_quantity,4)else balance_row.average_unit_cost end;insert into public.stock_movements(organization_id,inventory_item_id,location_id,movement_type,quantity_delta,unit_cost,balance_after,transfer_id,adjustment_id,reference_type,reference_id,notes,idempotency_key,created_by)values(requested_organization_id,requested_inventory_item_id,requested_location_id,requested_movement_type,requested_quantity_delta,requested_unit_cost,next_quantity,requested_transfer_id,requested_adjustment_id,requested_reference_type,requested_reference_id,nullif(btrim(requested_notes),''),requested_idempotency_key,requested_actor)returning id into target_id;update public.stock_balances set quantity=next_quantity,average_unit_cost=next_average,last_movement_at=now(),updated_at=now()where id=balance_row.id;perform set_config('app.inventory_projection_write','off',true);return target_id;exception when unique_violation then select id into target_id from public.stock_movements where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if target_id is null then raise;end if;return target_id;end;$$;
create function private.record_stock_movement(requested_organization_id uuid,requested_inventory_item_id uuid,requested_location_id uuid,requested_movement_type text,requested_quantity_delta numeric,requested_unit_cost numeric,requested_notes text,requested_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare branch uuid;begin select branch_id into branch from public.inventory_locations where id=requested_location_id and organization_id=requested_organization_id;if(select auth.uid())is null or not private.inventory_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'inventory.adjust',branch)then raise exception'Permission denied.'using errcode='42501';end if;if requested_movement_type not in('purchase','return','opening_balance','wastage')then raise exception'Use the dedicated business operation for this movement.'using errcode='22023';end if;return private.post_stock_movement(requested_organization_id,requested_inventory_item_id,requested_location_id,requested_movement_type,requested_quantity_delta,requested_unit_cost,null,null,'manual',null,requested_notes,requested_idempotency_key,(select auth.uid()));end;$$;

create function private.complete_stock_transfer(requested_organization_id uuid,requested_from_location_id uuid,requested_to_location_id uuid,requested_notes text,requested_idempotency_key text,requested_lines jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=gen_random_uuid();actor uuid:=(select auth.uid());item jsonb;source_branch uuid;target_branch uuid;source_cost numeric;begin select id into target_id from public.stock_transfers where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return target_id;end if;target_id:=gen_random_uuid();select branch_id into source_branch from public.inventory_locations where id=requested_from_location_id and organization_id=requested_organization_id and is_active;select branch_id into target_branch from public.inventory_locations where id=requested_to_location_id and organization_id=requested_organization_id and is_active;if actor is null or not private.inventory_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'inventory.transfer',source_branch)or not private.can_business_permission(requested_organization_id,'inventory.transfer',target_branch)then raise exception'Permission denied.'using errcode='42501';end if;if requested_from_location_id=requested_to_location_id or source_branch is null or target_branch is null or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)not between 1 and 200 then raise exception'Invalid stock transfer.'using errcode='22023';end if;insert into public.stock_transfers(id,organization_id,from_location_id,to_location_id,status,notes,idempotency_key,created_by)values(target_id,requested_organization_id,requested_from_location_id,requested_to_location_id,'draft',nullif(btrim(requested_notes),''),requested_idempotency_key,actor);for item in select value from jsonb_array_elements(requested_lines)order by value->>'inventoryItemId'loop if item-array['inventoryItemId','quantity','unitCost']::text[]<>'{}'::jsonb or not(item?&array['inventoryItemId','quantity'])or(item->>'quantity')::numeric<=0 then raise exception'Invalid transfer line.'using errcode='22023';end if;perform set_config('app.inventory_projection_write','on',true);insert into public.stock_balances(organization_id,inventory_item_id,location_id)values(requested_organization_id,(item->>'inventoryItemId')::uuid,requested_from_location_id),(requested_organization_id,(item->>'inventoryItemId')::uuid,requested_to_location_id)on conflict(organization_id,inventory_item_id,location_id)do nothing;perform set_config('app.inventory_projection_write','off',true);end loop;perform 1 from public.stock_balances balance where balance.organization_id=requested_organization_id and balance.location_id in(requested_from_location_id,requested_to_location_id)and balance.inventory_item_id in(select(value->>'inventoryItemId')::uuid from jsonb_array_elements(requested_lines))order by balance.inventory_item_id,balance.location_id for update;for item in select value from jsonb_array_elements(requested_lines)order by value->>'inventoryItemId'loop select average_unit_cost into source_cost from public.stock_balances where organization_id=requested_organization_id and inventory_item_id=(item->>'inventoryItemId')::uuid and location_id=requested_from_location_id;insert into public.stock_transfer_lines(organization_id,transfer_id,inventory_item_id,quantity,unit_cost)values(requested_organization_id,target_id,(item->>'inventoryItemId')::uuid,(item->>'quantity')::numeric,source_cost);perform private.post_stock_movement(requested_organization_id,(item->>'inventoryItemId')::uuid,requested_from_location_id,'transfer_out',-(item->>'quantity')::numeric,source_cost,target_id,null,'transfer',target_id,requested_notes,'transfer:'||target_id||':'||(item->>'inventoryItemId')||':out',actor);perform private.post_stock_movement(requested_organization_id,(item->>'inventoryItemId')::uuid,requested_to_location_id,'transfer_in',(item->>'quantity')::numeric,source_cost,target_id,null,'transfer',target_id,requested_notes,'transfer:'||target_id||':'||(item->>'inventoryItemId')||':in',actor);end loop;update public.stock_transfers set status='completed',completed_at=now()where id=target_id;return target_id;exception when unique_violation then select id into target_id from public.stock_transfers where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if target_id is null then raise;end if;return target_id;end;$$;

create function private.create_stock_adjustment(requested_organization_id uuid,requested_location_id uuid,requested_reason text,requested_physical_count boolean,requested_require_approval boolean,requested_approver_role_key text,requested_idempotency_key text,requested_lines jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=gen_random_uuid();actor uuid:=(select auth.uid());branch uuid;item jsonb;approval_id uuid;begin select id into target_id from public.stock_adjustments where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return target_id;end if;target_id:=gen_random_uuid();select branch_id into branch from public.inventory_locations where id=requested_location_id and organization_id=requested_organization_id;if actor is null or not private.inventory_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,case when requested_physical_count then'inventory.count'else'inventory.adjust'end,branch)then raise exception'Permission denied.'using errcode='42501';end if;if branch is null or char_length(btrim(requested_reason))not between 1 and 500 or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)not between 1 and 500 then raise exception'Invalid stock adjustment.'using errcode='22023';end if;insert into public.stock_adjustments(id,organization_id,location_id,reason,physical_count,status,idempotency_key,created_by)values(target_id,requested_organization_id,requested_location_id,btrim(requested_reason),requested_physical_count,case when requested_require_approval then'pending_approval'else'approved'end,requested_idempotency_key,actor);for item in select value from jsonb_array_elements(requested_lines)loop if item-array['inventoryItemId','countedQuantity','quantityDelta','unitCost']::text[]<>'{}'::jsonb or not(item?'inventoryItemId')or(requested_physical_count and not(item?'countedQuantity'))or(not requested_physical_count and not(item?'quantityDelta'))then raise exception'Invalid adjustment line.'using errcode='22023';end if;insert into public.stock_adjustment_lines(organization_id,adjustment_id,inventory_item_id,counted_quantity,requested_delta,unit_cost)values(requested_organization_id,target_id,(item->>'inventoryItemId')::uuid,case when item?'countedQuantity'then(item->>'countedQuantity')::numeric end,case when item?'quantityDelta'then(item->>'quantityDelta')::numeric end,case when item?'unitCost'then(item->>'unitCost')::numeric end);end loop;if requested_require_approval then approval_id:=private.create_approval_request(requested_organization_id,'inventory_adjustment','Inventory adjustment approval',requested_reason,null,null,null,jsonb_build_array(jsonb_build_object('key','inventory_review','name','Inventory adjustment review','approverRoleKey',requested_approver_role_key)));update public.stock_adjustments set approval_request_id=approval_id where id=target_id;end if;return target_id;exception when unique_violation then select id into target_id from public.stock_adjustments where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if target_id is null then raise;end if;return target_id;end;$$;
create function private.post_stock_adjustment(requested_organization_id uuid,requested_adjustment_id uuid)returns void language plpgsql security definer set search_path='' as $$declare adjustment public.stock_adjustments%rowtype;line public.stock_adjustment_lines%rowtype;balance_qty numeric;delta numeric;cost numeric;branch uuid;begin select*into adjustment from public.stock_adjustments where id=requested_adjustment_id and organization_id=requested_organization_id for update;select branch_id into branch from public.inventory_locations where id=adjustment.location_id;if(select auth.uid())is null or not private.can_business_permission(requested_organization_id,'inventory.adjust',branch)then raise exception'Permission denied.'using errcode='42501';end if;if adjustment.id is null or adjustment.status not in('approved','pending_approval')then raise exception'Adjustment cannot be posted.'using errcode='P0001';end if;if adjustment.status='pending_approval'and not exists(select 1 from public.approval_requests where id=adjustment.approval_request_id and organization_id=requested_organization_id and status='approved')then raise exception'Adjustment approval is still pending.'using errcode='P0001';end if;for line in select*from public.stock_adjustment_lines where adjustment_id=adjustment.id order by inventory_item_id loop perform set_config('app.inventory_projection_write','on',true);insert into public.stock_balances(organization_id,inventory_item_id,location_id)values(requested_organization_id,line.inventory_item_id,adjustment.location_id)on conflict(organization_id,inventory_item_id,location_id)do nothing;select quantity,average_unit_cost into balance_qty,cost from public.stock_balances where organization_id=requested_organization_id and inventory_item_id=line.inventory_item_id and location_id=adjustment.location_id for update;delta:=case when adjustment.physical_count then line.counted_quantity-balance_qty else line.requested_delta end;update public.stock_adjustment_lines set system_quantity=balance_qty,posted_delta=delta where id=line.id;if delta<>0 then perform private.post_stock_movement(requested_organization_id,line.inventory_item_id,adjustment.location_id,'adjustment',delta,coalesce(line.unit_cost,cost),null,adjustment.id,'adjustment',adjustment.id,adjustment.reason,'adjustment:'||adjustment.id||':'||line.inventory_item_id,(select auth.uid()));end if;end loop;update public.stock_adjustments set status='posted',posted_at=now()where id=adjustment.id;perform set_config('app.inventory_projection_write','off',true);end;$$;

create function public.configure_inventory_item(requested_organization_id uuid,requested_inventory_item_id uuid,requested_product_variant_id uuid,requested_low_stock_threshold numeric,requested_reorder_level numeric,requested_is_tracked boolean)returns uuid language sql security definer set search_path='' as $$select private.configure_inventory_item(requested_organization_id,requested_inventory_item_id,requested_product_variant_id,requested_low_stock_threshold,requested_reorder_level,requested_is_tracked);$$;create function public.save_inventory_location(requested_organization_id uuid,requested_location_id uuid,requested_branch_id uuid,requested_code text,requested_name text,requested_type text,requested_is_active boolean)returns uuid language sql security definer set search_path='' as $$select private.save_inventory_location(requested_organization_id,requested_location_id,requested_branch_id,requested_code,requested_name,requested_type,requested_is_active);$$;create function public.record_stock_movement(requested_organization_id uuid,requested_inventory_item_id uuid,requested_location_id uuid,requested_movement_type text,requested_quantity_delta numeric,requested_unit_cost numeric,requested_notes text,requested_idempotency_key text)returns uuid language sql security definer set search_path='' as $$select private.record_stock_movement(requested_organization_id,requested_inventory_item_id,requested_location_id,requested_movement_type,requested_quantity_delta,requested_unit_cost,requested_notes,requested_idempotency_key);$$;create function public.complete_stock_transfer(requested_organization_id uuid,requested_from_location_id uuid,requested_to_location_id uuid,requested_notes text,requested_idempotency_key text,requested_lines jsonb)returns uuid language sql security definer set search_path='' as $$select private.complete_stock_transfer(requested_organization_id,requested_from_location_id,requested_to_location_id,requested_notes,requested_idempotency_key,requested_lines);$$;create function public.create_stock_adjustment(requested_organization_id uuid,requested_location_id uuid,requested_reason text,requested_physical_count boolean,requested_require_approval boolean,requested_approver_role_key text,requested_idempotency_key text,requested_lines jsonb)returns uuid language sql security definer set search_path='' as $$select private.create_stock_adjustment(requested_organization_id,requested_location_id,requested_reason,requested_physical_count,requested_require_approval,requested_approver_role_key,requested_idempotency_key,requested_lines);$$;create function public.post_stock_adjustment(requested_organization_id uuid,requested_adjustment_id uuid)returns void language sql security definer set search_path='' as $$select private.post_stock_adjustment(requested_organization_id,requested_adjustment_id);$$;
